INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2016-01-01-switzerland-federal-suppliers-must-invoice-electronically', '2016-01-01', '2016-01', 'The obligation the Federal Council decided in October 2014 takes effect. It binds the supplier to issue, not the authority to receive — and the binding text is a clause in the Confederation''s procurement terms, not an ordinance.', '<h3>🇨🇭 Federal suppliers must invoice electronically above CHF 5,000</h3><p>From today, a supplier to the Swiss federal administration must submit an electronic invoice where the contract value exceeds CHF 5,000. The Federal Council resolved this on 8 October 2014, setting the threshold to spare smaller suppliers.</p><p>Two features make it unlike most B2G mandates. First, it binds the <strong>supplier to issue</strong> rather than the authority to receive — the opposite polarity to the EU directive regime, which Switzerland is not part of. Second, there is no ordinance behind it: the binding text is clause 9.4 of the Confederation''s procurement standard terms, resting on the Federal Council''s decision. A reader looking for a law will not find one.</p><p>Two details worth carrying. The threshold is CHF 5,000 <em>excluding VAT</em>, a qualifier that appears only in the standard terms and not on any official prose page. And the obligation reaches the central federal administration only — cantons, communes and the ETH domain are outside it, and the Federal Finance Administration publishes the list that settles any given counterparty.</p>', 'https://www.vtg.admin.ch/de/e-rechnung', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2016-01-01-switzerland-federal-suppliers-must-invoice-electronically', id FROM countries WHERE code = 'CH';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2016-01-01-switzerland-federal-suppliers-must-invoice-electronically', 'en', '🇨🇭 Federal suppliers must invoice electronically above CHF 5,000', 'The obligation the Federal Council decided in October 2014 takes effect. It binds the supplier to issue, not the authority to receive — and the binding text is a clause in the Confederation''s procurement terms, not an ordinance.', '<h3>🇨🇭 Federal suppliers must invoice electronically above CHF 5,000</h3><p>From today, a supplier to the Swiss federal administration must submit an electronic invoice where the contract value exceeds CHF 5,000. The Federal Council resolved this on 8 October 2014, setting the threshold to spare smaller suppliers.</p><p>Two features make it unlike most B2G mandates. First, it binds the <strong>supplier to issue</strong> rather than the authority to receive — the opposite polarity to the EU directive regime, which Switzerland is not part of. Second, there is no ordinance behind it: the binding text is clause 9.4 of the Confederation''s procurement standard terms, resting on the Federal Council''s decision. A reader looking for a law will not find one.</p><p>Two details worth carrying. The threshold is CHF 5,000 <em>excluding VAT</em>, a qualifier that appears only in the standard terms and not on any official prose page. And the obligation reaches the central federal administration only — cantons, communes and the ETH domain are outside it, and the Federal Finance Administration publishes the list that settles any given counterparty.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2016-01-01-switzerland-federal-suppliers-must-invoice-electronically', 'es', '🇨🇭 Los proveedores federales deben facturar electrónicamente por encima de 5.000 CHF', 'Entra en vigor la obligación que el Consejo Federal decidió en octubre de 2014. Vincula al proveedor a emitir, no al organismo a recibir, y el texto vinculante es una cláusula de las condiciones de contratación, no un reglamento.', '<h3>🇨🇭 Los proveedores federales deben facturar electrónicamente por encima de 5.000 CHF</h3><p>Desde hoy, un proveedor de la administración federal suiza debe presentar una factura electrónica cuando el valor del contrato supere los 5.000 francos. El Consejo Federal lo resolvió el 8 de octubre de 2014 y fijó el umbral para no cargar a los proveedores más pequeños.</p><p>Dos rasgos la distinguen de la mayoría de obligaciones B2G. Primero, vincula al <strong>proveedor a emitir</strong> y no al organismo a recibir: la polaridad opuesta al régimen de la directiva de la UE, del que Suiza no forma parte. Segundo, no hay reglamento detrás: el texto vinculante es la cláusula 9.4 de las condiciones generales de contratación de la Confederación, apoyada en la decisión del Consejo Federal. Quien busque una ley no la encontrará.</p><p>Dos detalles que conviene retener. El umbral es de 5.000 francos <em>sin IVA</em>, matiz que solo aparece en las condiciones generales y en ninguna página oficial en prosa. Y la obligación alcanza únicamente a la administración federal central: cantones, municipios y el ámbito de las EPF quedan fuera, y la Administración Federal de Finanzas publica la lista que resuelve cada contraparte.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2016-01-01-switzerland-federal-suppliers-must-invoice-electronically', 'de', '🇨🇭 Bundeslieferanten müssen über 5''000 CHF elektronisch fakturieren', 'Die im Oktober 2014 vom Bundesrat beschlossene Pflicht tritt in Kraft. Sie bindet den Lieferanten zum Ausstellen, nicht die Behörde zum Empfangen -- und der verbindliche Text ist eine Ziffer der AGB des Bundes, keine Verordnung.', '<h3>🇨🇭 Bundeslieferanten müssen über 5''000 CHF elektronisch fakturieren</h3><p>Ab heute muss ein Lieferant der schweizerischen Bundesverwaltung eine elektronische Rechnung einreichen, wenn der Vertragswert 5''000 Franken übersteigt. Der Bundesrat beschloss dies am 8. Oktober 2014 und setzte die Schwelle, um kleinere Lieferanten zu schonen.</p><p>Zwei Merkmale unterscheiden sie von den meisten B2G-Pflichten. Erstens bindet sie den <strong>Lieferanten zum Ausstellen</strong> und nicht die Behörde zum Empfangen -- die umgekehrte Polarität zum Regime der EU-Richtlinie, dem die Schweiz nicht angehört. Zweitens steht keine Verordnung dahinter: der verbindliche Text ist Ziffer 9.4 der AGB des Bundes, gestützt auf den Bundesratsbeschluss. Wer ein Gesetz sucht, findet keines.</p><p>Zwei Details lohnen die Mitnahme. Die Schwelle beträgt 5''000 Franken <em>exklusive MWST</em>, ein Zusatz, der nur in den AGB steht und auf keiner amtlichen Fliesstextseite. Und die Pflicht erreicht allein die zentrale Bundesverwaltung -- Kantone, Gemeinden und der ETH-Bereich liegen ausserhalb, und die Eidgenössische Finanzverwaltung führt die Liste, die jede Gegenpartei klärt.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2016-01-01-switzerland-federal-suppliers-must-invoice-electronically', 'fr', '🇨🇭 Les fournisseurs fédéraux doivent facturer par voie électronique au-delà de 5 000 CHF', 'L''obligation décidée par le Conseil fédéral en octobre 2014 entre en vigueur. Elle lie le fournisseur à émettre, non l''autorité à recevoir — et le texte contraignant est une clause des conditions générales, non une ordonnance.', '<h3>🇨🇭 Les fournisseurs fédéraux doivent facturer par voie électronique au-delà de 5 000 CHF</h3><p>À compter d''aujourd''hui, un fournisseur de l''administration fédérale suisse doit remettre une facture électronique lorsque la valeur du contrat dépasse 5 000 francs. Le Conseil fédéral l''a décidé le 8 octobre 2014, fixant le seuil pour épargner les plus petits fournisseurs.</p><p>Deux traits la distinguent de la plupart des obligations B2G. D''abord, elle lie le <strong>fournisseur à émettre</strong> et non l''autorité à recevoir : la polarité inverse du régime de la directive européenne, auquel la Suisse n''appartient pas. Ensuite, aucune ordonnance ne la porte : le texte contraignant est la clause 9.4 des conditions générales de la Confédération, adossée à la décision du Conseil fédéral. Qui cherche une loi n''en trouvera pas.</p><p>Deux détails à retenir. Le seuil est de 5 000 francs <em>hors TVA</em>, précision qui ne figure que dans les conditions générales et sur aucune page officielle en prose. Et l''obligation n''atteint que l''administration fédérale centrale — cantons, communes et domaine des EPF en sont exclus, et l''Administration fédérale des finances publie la liste qui tranche pour chaque contrepartie.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2018-06-27-switzerland-a-pdf-by-email-counts', '2018-06-27', '2018-06', 'Reporting a fourfold rise in e-invoice share, the Confederation confirmed that PDF invoices sent by e-mail satisfy the obligation. The duty is to invoice without paper, not in a structured format.', '<h3>🇨🇭 A PDF by e-mail counts — the quiet fact that reshapes the Swiss mandate</h3><p>The Federal Finance Administration reported today that the share of electronic invoices reaching the Confederation has risen fourfold, to around 60 per cent — and confirmed, in the same release, that the federal administration also accepts <strong>PDF invoices sent by e-mail</strong>.</p><p>That single sentence is the most consequential fact about Swiss e-invoicing, and it is almost always omitted. "Switzerland: B2G mandatory since 2016" reads exactly like Italy or France to anyone scoping a project. It is not the same thing. The Swiss duty is that the invoice must not be <em>paper</em>; it is not that the invoice must be <em>structured</em>. There is no EN 16931 requirement, no Peppol access point, no clearance step and no national platform.</p><p>The practical consequence runs in one direction: a supplier who provisions a structured e-invoicing pipeline purely to satisfy the Swiss federal rule has bought something the rule never asked for. Structured data remains available through a service provider, and is worth having for automation — but that is an operational choice, not compliance.</p>', 'https://www.admin.ch/de/nsb?id=71361', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2018-06-27-switzerland-a-pdf-by-email-counts', id FROM countries WHERE code = 'CH';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2018-06-27-switzerland-a-pdf-by-email-counts', 'en', '🇨🇭 A PDF by e-mail counts — the quiet fact that reshapes the Swiss mandate', 'Reporting a fourfold rise in e-invoice share, the Confederation confirmed that PDF invoices sent by e-mail satisfy the obligation. The duty is to invoice without paper, not in a structured format.', '<h3>🇨🇭 A PDF by e-mail counts — the quiet fact that reshapes the Swiss mandate</h3><p>The Federal Finance Administration reported today that the share of electronic invoices reaching the Confederation has risen fourfold, to around 60 per cent — and confirmed, in the same release, that the federal administration also accepts <strong>PDF invoices sent by e-mail</strong>.</p><p>That single sentence is the most consequential fact about Swiss e-invoicing, and it is almost always omitted. "Switzerland: B2G mandatory since 2016" reads exactly like Italy or France to anyone scoping a project. It is not the same thing. The Swiss duty is that the invoice must not be <em>paper</em>; it is not that the invoice must be <em>structured</em>. There is no EN 16931 requirement, no Peppol access point, no clearance step and no national platform.</p><p>The practical consequence runs in one direction: a supplier who provisions a structured e-invoicing pipeline purely to satisfy the Swiss federal rule has bought something the rule never asked for. Structured data remains available through a service provider, and is worth having for automation — but that is an operational choice, not compliance.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2018-06-27-switzerland-a-pdf-by-email-counts', 'es', '🇨🇭 Un PDF por correo vale: el dato discreto que reconfigura la obligación suiza', 'Al informar de que la cuota de factura electrónica se había cuadruplicado, la Confederación confirmó que las facturas en PDF enviadas por correo satisfacen la obligación. El deber es facturar sin papel, no en formato estructurado.', '<h3>🇨🇭 Un PDF por correo vale: el dato discreto que reconfigura la obligación suiza</h3><p>La Administración Federal de Finanzas informó hoy de que la proporción de facturas electrónicas que llegan a la Confederación se ha cuadruplicado, hasta cerca del 60 %, y confirmó en el mismo comunicado que la administración federal acepta también <strong>facturas en PDF enviadas por correo electrónico</strong>.</p><p>Esa sola frase es el dato más determinante de la facturación electrónica suiza, y casi siempre se omite. «Suiza: B2G obligatorio desde 2016» se lee igual que Italia o Francia para quien dimensiona un proyecto. No es lo mismo. El deber suizo es que la factura no sea <em>de papel</em>; no que la factura sea <em>estructurada</em>. No hay requisito EN 16931, ni punto de acceso Peppol, ni paso de autorización, ni plataforma nacional.</p><p>La consecuencia práctica va en una sola dirección: el proveedor que despliega una cadena estructurada solo para satisfacer la norma federal suiza ha comprado algo que la norma nunca pidió. Los datos estructurados siguen disponibles vía proveedor de servicios y valen la pena por la automatización, pero eso es una decisión operativa, no cumplimiento.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2018-06-27-switzerland-a-pdf-by-email-counts', 'de', '🇨🇭 Ein PDF per E-Mail genügt — die leise Tatsache, die die Schweizer Pflicht umformt', 'Bei der Meldung einer Vervierfachung des E-Rechnungs-Anteils bestätigte der Bund, dass per E-Mail gesandte PDF-Rechnungen die Pflicht erfüllen. Die Pflicht lautet, ohne Papier zu fakturieren, nicht strukturiert.', '<h3>🇨🇭 Ein PDF per E-Mail genügt — die leise Tatsache, die die Schweizer Pflicht umformt</h3><p>Die Eidgenössische Finanzverwaltung meldete heute, der Anteil elektronischer Rechnungen an den Bund habe sich vervierfacht, auf rund 60 Prozent -- und bestätigte in derselben Mitteilung, dass die Bundesverwaltung auch <strong>per E-Mail gesandte PDF-Rechnungen</strong> akzeptiert.</p><p>Dieser eine Satz ist die folgenreichste Tatsache der schweizerischen E-Rechnung, und er fehlt fast immer. «Schweiz: B2G verpflichtend seit 2016» liest sich für jede Projektplanung genau wie Italien oder Frankreich. Es ist nicht dasselbe. Die Schweizer Pflicht lautet, dass die Rechnung kein <em>Papier</em> sein darf; nicht, dass sie <em>strukturiert</em> sein muss. Es gibt keine EN-16931-Anforderung, keinen Peppol-Zugangspunkt, keinen Freigabeschritt und keine nationale Plattform.</p><p>Die praktische Folge läuft in eine Richtung: Wer eine strukturierte Strecke allein zur Erfüllung der schweizerischen Bundesregel aufbaut, hat etwas gekauft, das die Regel nie verlangt hat. Strukturierte Daten bleiben über einen Service-Provider verfügbar und lohnen sich für die Automatisierung -- doch das ist eine betriebliche Entscheidung, keine Befolgung.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2018-06-27-switzerland-a-pdf-by-email-counts', 'fr', '🇨🇭 Un PDF par courriel suffit — le fait discret qui reconfigure l''obligation suisse', 'En annonçant un quadruplement de la part des factures électroniques, la Confédération a confirmé que les factures PDF envoyées par courriel satisfont l''obligation. Le devoir est de facturer sans papier, non en format structuré.', '<h3>🇨🇭 Un PDF par courriel suffit — le fait discret qui reconfigure l''obligation suisse</h3><p>L''Administration fédérale des finances a annoncé aujourd''hui que la part des factures électroniques parvenant à la Confédération avait quadruplé, pour atteindre environ 60 %, et a confirmé dans le même communiqué que l''administration fédérale accepte aussi les <strong>factures PDF envoyées par courriel</strong>.</p><p>Cette seule phrase est le fait le plus lourd de conséquences de la facturation électronique suisse, et elle est presque toujours omise. « Suisse : B2G obligatoire depuis 2016 » se lit exactement comme l''Italie ou la France pour qui cadre un projet. Ce n''est pas la même chose. L''obligation suisse est que la facture ne soit pas du <em>papier</em> ; non qu''elle soit <em>structurée</em>. Il n''y a ni exigence EN 16931, ni point d''accès Peppol, ni étape de validation, ni plateforme nationale.</p><p>La conséquence pratique va dans un seul sens : le fournisseur qui déploie une chaîne structurée dans le seul but de satisfaire la règle fédérale suisse a acheté ce que la règle n''a jamais demandé. Les données structurées restent accessibles via un prestataire et valent pour l''automatisation — mais c''est un choix opérationnel, non de la conformité.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2026-08-27-switzerland-liechtenstein-one-vat-law-opposite-duties', '2026-08-27', '2026-08', 'The two countries share a VAT statute in substance and have e-invoicing obligations that run in opposite directions, from different bodies of law. It is the clearest illustration that a shared tax law implies nothing about e-invoicing.', '<h3>🇨🇭 One VAT law, opposite duties: Switzerland and Liechtenstein compared</h3><p>Swiss VAT law governs in Liechtenstein under the treaty of 28 October 1994, through Liechtenstein''s own act and its own tax administration. Rates, thresholds, invoice content and the absence of any signature requirement all flow from the same source. You might reasonably expect their e-invoicing positions to match. They are opposites in every dimension that matters.</p><p><strong>Who is bound.</strong> Switzerland binds the supplier to issue. Liechtenstein binds the contracting authority to receive. A Swiss federal supplier must send an electronic invoice; a Liechtenstein supplier may, and the authority must be able to handle it.</p><p><strong>From what source.</strong> Switzerland''s duty is contractual — clause 9.4 of the Confederation''s procurement standard terms, resting on a Federal Council decision of October 2014. Liechtenstein''s is EEA-derived: Directive 2014/55/EU incorporated by Joint Committee Decision 166/2015 and transposed in its procurement act.</p><p><strong>From when.</strong> Switzerland since January 2016; Liechtenstein since November 2018.</p><p><strong>And what neither has.</strong> No B2B or B2C mandate, no transaction reporting, no Peppol authority. Both made electronic VAT filing compulsory — Liechtenstein in January 2025, Switzerland in the same month — and in both cases that is a filing channel and not a reporting regime.</p><p>The reason the two diverge is that the treaty covers tax and not procurement, and the EEA Agreement covers procurement and not tax. Each country took its e-invoicing rule from the body of law the other one is outside. If you run entities in both, do not reason from one to the other.</p>', 'https://www.efv.admin.ch/de/e-rechnungen-zustellen', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-08-27-switzerland-liechtenstein-one-vat-law-opposite-duties', id FROM countries WHERE code = 'CH';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-08-27-switzerland-liechtenstein-one-vat-law-opposite-duties', 'en', '🇨🇭 One VAT law, opposite duties: Switzerland and Liechtenstein compared', 'The two countries share a VAT statute in substance and have e-invoicing obligations that run in opposite directions, from different bodies of law. It is the clearest illustration that a shared tax law implies nothing about e-invoicing.', '<h3>🇨🇭 One VAT law, opposite duties: Switzerland and Liechtenstein compared</h3><p>Swiss VAT law governs in Liechtenstein under the treaty of 28 October 1994, through Liechtenstein''s own act and its own tax administration. Rates, thresholds, invoice content and the absence of any signature requirement all flow from the same source. You might reasonably expect their e-invoicing positions to match. They are opposites in every dimension that matters.</p><p><strong>Who is bound.</strong> Switzerland binds the supplier to issue. Liechtenstein binds the contracting authority to receive. A Swiss federal supplier must send an electronic invoice; a Liechtenstein supplier may, and the authority must be able to handle it.</p><p><strong>From what source.</strong> Switzerland''s duty is contractual — clause 9.4 of the Confederation''s procurement standard terms, resting on a Federal Council decision of October 2014. Liechtenstein''s is EEA-derived: Directive 2014/55/EU incorporated by Joint Committee Decision 166/2015 and transposed in its procurement act.</p><p><strong>From when.</strong> Switzerland since January 2016; Liechtenstein since November 2018.</p><p><strong>And what neither has.</strong> No B2B or B2C mandate, no transaction reporting, no Peppol authority. Both made electronic VAT filing compulsory — Liechtenstein in January 2025, Switzerland in the same month — and in both cases that is a filing channel and not a reporting regime.</p><p>The reason the two diverge is that the treaty covers tax and not procurement, and the EEA Agreement covers procurement and not tax. Each country took its e-invoicing rule from the body of law the other one is outside. If you run entities in both, do not reason from one to the other.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-08-27-switzerland-liechtenstein-one-vat-law-opposite-duties', 'es', '🇨🇭 Una ley del IVA, deberes opuestos: Suiza y Liechtenstein comparados', 'Ambos países comparten una ley del IVA en lo sustancial y tienen obligaciones de facturación electrónica que van en sentidos opuestos, desde cuerpos jurídicos distintos. Es la ilustración más clara de que compartir una ley tributaria no implica nada sobre facturación.', '<h3>🇨🇭 Una ley del IVA, deberes opuestos: Suiza y Liechtenstein comparados</h3><p>La ley suiza del IVA rige en Liechtenstein por el tratado de 28 de octubre de 1994, a través de la ley propia de Liechtenstein y de su propia administración tributaria. Tipos, umbrales, contenido de la factura y la ausencia de todo requisito de firma proceden de la misma fuente. Cabría esperar que sus posiciones de facturación electrónica coincidieran. Son opuestas en todas las dimensiones que importan.</p><p><strong>Quién queda obligado.</strong> Suiza obliga al proveedor a emitir. Liechtenstein obliga al organismo contratante a recibir. Un proveedor federal suizo debe enviar factura electrónica; uno de Liechtenstein puede, y el organismo debe poder tramitarla.</p><p><strong>Desde qué fuente.</strong> El deber suizo es contractual: la cláusula 9.4 de las condiciones generales de contratación de la Confederación, apoyada en una decisión del Consejo Federal de octubre de 2014. El de Liechtenstein deriva del EEE: la Directiva 2014/55/UE incorporada por la Decisión 166/2015 del Comité Mixto y transpuesta en su ley de contratación.</p><p><strong>Desde cuándo.</strong> Suiza desde enero de 2016; Liechtenstein desde noviembre de 2018.</p><p><strong>Y qué no tiene ninguno.</strong> Ni obligación B2B ni B2C, ni declaración de operaciones, ni autoridad Peppol. Ambos hicieron obligatoria la declaración electrónica del IVA —Liechtenstein en enero de 2025, Suiza el mismo mes— y en ambos casos es un canal de presentación y no un régimen de declaración.</p><p>La razón de la divergencia es que el tratado cubre la fiscalidad y no la contratación, y el Acuerdo EEE cubre la contratación y no la fiscalidad. Cada país tomó su norma de facturación electrónica del cuerpo jurídico del que el otro queda fuera. Si opera entidades en ambos, no razone de uno al otro.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-08-27-switzerland-liechtenstein-one-vat-law-opposite-duties', 'de', '🇨🇭 Ein Mehrwertsteuergesetz, entgegengesetzte Pflichten: die Schweiz und Liechtenstein im Vergleich', 'Die beiden Länder teilen inhaltlich ein Mehrwertsteuergesetz und haben E-Rechnungs-Pflichten, die in entgegengesetzte Richtungen laufen, aus verschiedenen Rechtsgebieten. Die klarste Illustration dafür, dass geteiltes Steuerrecht nichts über E-Rechnung aussagt.', '<h3>🇨🇭 Ein Mehrwertsteuergesetz, entgegengesetzte Pflichten: die Schweiz und Liechtenstein im Vergleich</h3><p>Schweizerisches MWST-Recht gilt in Liechtenstein kraft des Staatsvertrags vom 28. Oktober 1994, über Liechtensteins eigenes Gesetz und seine eigene Steuerverwaltung. Sätze, Schwellen, Rechnungsinhalt und das Fehlen jeder Signaturpflicht stammen aus derselben Quelle. Man könnte erwarten, dass ihre E-Rechnungs-Positionen übereinstimmen. Sie sind in jeder wesentlichen Dimension Gegenteile.</p><p><strong>Wer gebunden ist.</strong> Die Schweiz bindet den Lieferanten zum Ausstellen. Liechtenstein bindet den Auftraggeber zum Empfangen. Ein schweizerischer Bundeslieferant muss elektronisch fakturieren; ein liechtensteinischer darf, und die Behörde muss damit umgehen können.</p><p><strong>Aus welcher Quelle.</strong> Die schweizerische Pflicht ist vertraglich -- Ziffer 9.4 der AGB des Bundes, gestützt auf einen Bundesratsbeschluss vom Oktober 2014. Die liechtensteinische ist EWR-abgeleitet: Richtlinie 2014/55/EU, übernommen durch Beschluss 166/2015 des Gemeinsamen Ausschusses und umgesetzt im Beschaffungsgesetz.</p><p><strong>Seit wann.</strong> Die Schweiz seit Januar 2016; Liechtenstein seit November 2018.</p><p><strong>Und was keines hat.</strong> Keine B2B- oder B2C-Pflicht, keine Transaktionsmeldung, keine Peppol-Behörde. Beide machten die elektronische MWST-Abrechnung zwingend -- Liechtenstein im Januar 2025, die Schweiz im selben Monat -- und in beiden Fällen ist das ein Einreichungskanal und kein Meldeverfahren.</p><p>Der Grund der Divergenz: Der Staatsvertrag erfasst Steuern und nicht Beschaffung, das EWR-Abkommen erfasst Beschaffung und nicht Steuern. Jedes Land nahm seine E-Rechnungs-Regel aus dem Rechtsgebiet, ausserhalb dessen das andere steht. Wer in beiden Gesellschaften führt, sollte nicht vom einen auf das andere schliessen.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-08-27-switzerland-liechtenstein-one-vat-law-opposite-duties', 'fr', '🇨🇭 Une loi TVA, des obligations inverses : la Suisse et le Liechtenstein comparés', 'Les deux pays partagent une loi TVA sur le fond et ont des obligations de facturation électronique qui vont en sens inverse, depuis des corps de règles différents. L''illustration la plus nette qu''une loi fiscale partagée n''implique rien en matière de facturation.', '<h3>🇨🇭 Une loi TVA, des obligations inverses : la Suisse et le Liechtenstein comparés</h3><p>Le droit suisse de la TVA s''applique au Liechtenstein par le traité du 28 octobre 1994, à travers la loi propre au Liechtenstein et sa propre administration fiscale. Taux, seuils, contenu des factures et absence de toute exigence de signature découlent de la même source. On pourrait s''attendre à ce que leurs positions sur la facturation électronique concordent. Elles sont inverses dans toutes les dimensions qui comptent.</p><p><strong>Qui est tenu.</strong> La Suisse lie le fournisseur à émettre. Le Liechtenstein lie le pouvoir adjudicateur à recevoir. Un fournisseur fédéral suisse doit envoyer une facture électronique ; un fournisseur liechtensteinois le peut, et l''autorité doit pouvoir la traiter.</p><p><strong>Depuis quelle source.</strong> L''obligation suisse est contractuelle — la clause 9.4 des conditions générales de la Confédération, adossée à une décision du Conseil fédéral d''octobre 2014. Celle du Liechtenstein est issue de l''EEE : la directive 2014/55/UE reprise par la décision 166/2015 du Comité mixte et transposée dans sa loi sur les marchés publics.</p><p><strong>Depuis quand.</strong> La Suisse depuis janvier 2016 ; le Liechtenstein depuis novembre 2018.</p><p><strong>Et ce qu''aucun des deux n''a.</strong> Aucune obligation B2B ou B2C, aucune déclaration de transactions, aucune autorité Peppol. Tous deux ont rendu la déclaration électronique de TVA obligatoire — le Liechtenstein en janvier 2025, la Suisse le même mois — et dans les deux cas il s''agit d''un canal de dépôt et non d''un régime déclaratif.</p><p>La raison de la divergence : le traité couvre la fiscalité et non la commande publique, et l''accord EEE couvre la commande publique et non la fiscalité. Chaque pays a tiré sa règle de facturation du corps de règles dont l''autre est exclu. Si vous pilotez des entités dans les deux, ne raisonnez pas de l''un vers l''autre.</p>');

